// Which completed bookings the "ready to pull" lists show.
//
// "all" is the default because a counter payment no longer settles a lesson for
// invoicing purposes - see addCompletedBookingLine. Taking payment at the till
// and invoicing the range for the same lesson are two different transactions,
// so a paid lesson has to stay in the working list.
//
// "unpaid" is for the other way of working: treat a counter payment as the end
// of it and only ever invoice what has not been paid. "paid" is for looking
// back at what has been settled.
type BookingPullFilter = "unpaid" | "all" | "paid";
// v2: the stored value is deliberately re-keyed. Everyone currently has
// "unpaid" saved from when that was the default, and reusing the old key would
// leave them with paid lessons hidden from a list that now expects to show them.
const BOOKING_PULL_FILTER_STORAGE_KEY = "clarity.billing.pullFilter.v2";

function readStoredPullFilter(): BookingPullFilter {
  if (typeof window === "undefined") return "all";
  const stored = window.localStorage.getItem(BOOKING_PULL_FILTER_STORAGE_KEY);
  return stored === "unpaid" || stored === "paid" ? stored : "all";
}
// A money-out bank transaction (Akahu) awaiting review as an expense.
type BankExpenseCandidate = {
  id: string;
  date: string;
  amount: number;
  description: string | null;
  merchant: string | null;
  type: string | null;
  suggestedCategory: string | null;
  accountId: string | null;
  account: string | null;
};
type BankExpenseSortKey = "date" | "account" | "description" | "amount";
type BankExpenseSortDirection = "asc" | "desc";
type BankExpenseSort = { key: BankExpenseSortKey; direction: BankExpenseSortDirection };
// A money-in bank transaction awaiting reconciliation against an invoice.
type ReconcileSuggestion = {
  invoiceId: string;
  invoiceNumber: string;
  customer: string | null;
  total: number;
  outstanding: number;
  refMatch: boolean;
  amountMatch: boolean;
};
type ReconcileCandidate = {
  id: string;
  date: string;
  amount: number;
  description: string | null;
  account: string | null;
  reference: string | null;
  // Akahu enrichment used for filtering (same smart allocation the expense
  // review uses): the transaction type (e.g. "TRANSFER") and category.
  type: string | null;
  category: string | null;
  autoInvoiceId: string | null;
  suggestions: ReconcileSuggestion[];
};
// Normalise an Akahu transaction type into a short filter label. Internal
// transfers are the main thing to keep out of the reconcile list (they aren't
// customer payments), so they collapse to a single "Transfer" bucket.
function reconcileTypeLabel(type: string | null | undefined): string {
  const raw = (type || "").trim().toUpperCase();
  if (!raw) return "Other";
  if (raw.includes("TRANSFER")) return "Transfer";
  return raw
    .toLowerCase()
    .split(/\s+/)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

// Normalise a suggested expense classification (Akahu category enrichment) into
// a filter label. Transactions with no enrichment collapse to "Uncategorised".
function expenseCategoryLabel(category: string | null | undefined): string {
  return (category || "").trim() || "Uncategorised";
}

function bankCandidateSearchText(candidate: BankExpenseCandidate) {
  return [
    candidate.date,
    candidate.account,
    candidate.description,
    candidate.merchant,
    candidate.suggestedCategory,
    candidate.type,
    String(candidate.amount || ""),
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function bankCandidateSortText(value: string | null | undefined) {
  return (value || "").trim().toLowerCase();
}

/**
 * Settings sections, in the order they appear in the sub-nav.
 *
 * Was eleven tabs, several of which were the same screen under two names —
 * "Customer Experience" and "Coach Branding" showed an identical set of four
 * panels, because every one of them was classed onto both. These six are what
 * is left once each panel is filed once.
 *
 * Missing on purpose: Payments. Invoicing defaults, tax and payment terms all
 * live inside the Coach Account panel today, and pulling them out is a job
 * about that panel rather than about the filing.
 */
/**
 * A collapsible settings group.
 *
 * Settings used to show everything at once: eleven tabs, and every panel on the
 * open one expanded. Six sections fixed half of that; this fixes the rest.
 *
 * The header holds a title and a caret and nothing else — no summary line, no
 * count. A count in a header is information you cannot act on, placed where you
 * click, and it makes every header a different width.
 *
 * `inert` while closed is the part that is easy to leave out and expensive to
 * omit: without it a collapsed Account section keeps a tabbable Change
 * Password, Export and Close account in the DOM, so a keyboard user tabs
 * through controls nobody can see.
 */
const SettingsGroupContext = createContext<{
  openGroup: string;
  setOpenGroup: (id: string) => void;
} | null>(null);

function SettingsGroups({ children }: { children: ReactNode }) {
  // One value. Which group is open and which header is highlighted are the same
  // fact, so they cannot disagree.
  const [openGroup, setOpenGroup] = useState("");
  const value = useMemo(() => ({ openGroup, setOpenGroup }), [openGroup]);
  return <SettingsGroupContext.Provider value={value}>{children}</SettingsGroupContext.Provider>;
}

function SettingsGroup({
  id,
  section,
  title,
  className = "",
  children,
}: {
  id: string;
  section: string;
  title: string;
  className?: string;
  children: ReactNode;
}) {
  const context = useContext(SettingsGroupContext);
  // Every section arrives shut. A tab that opens with one section already
  // expanded pushes the rest below the fold and makes that one look like the
  // screen rather than one choice among several.
  const open = context ? context.openGroup === id : true;
  return (
    <article
      className={`data-card settings-section settings-${section} settings-group${open ? " is-open" : ""}${className ? ` ${className}` : ""}`}
    >
      <button
        className="settings-group-header"
        aria-expanded={open}
        onClick={() => context?.setOpenGroup(open ? "" : id)}
        type="button"
      >
        <span>{title}</span>
        <span className="settings-group-caret" aria-hidden="true">▾</span>
      </button>
      <div className={`disclosure-wrap${open ? " is-open" : ""}`} inert={!open}>
        <div className="disclosure-body settings-group-body">{children}</div>
      </div>
    </article>
  );
}

/**
 * The sub-nav, as data.
 *
 * One list drives the rows, the highlight and the admin gating, so a section
 * cannot exist in the nav and nowhere else — which is how "Customer
 * Experience" and "Coach Branding" both survived pointing at the same panels.
 */
const SETTINGS_SECTIONS: Array<{
  key: Exclude<SettingsTab, "none">;
  label: string;
  icon: typeof Settings;
  adminOnly?: boolean;
  /** Platform staff only. Not a business owner, however senior. */
  platformOnly?: boolean;
}> = [
  { key: "business", label: "Business", icon: Building2, adminOnly: true },
  { key: "booking", label: "Booking", icon: CalendarDays },
  { key: "services", label: "Lesson types", icon: ScissorsLineDashed },
  { key: "practice", label: "Practice", icon: ClipboardList },
  { key: "notifications", label: "Notifications", icon: Bell, adminOnly: true },
  { key: "account", label: "Account", icon: User, adminOnly: true },
  // Two lists, two questions. Integrations is "what have I plugged in" — the
  // coach's own accounts. Admin is "what is this software made of" — the
  // services Clarity runs on, which a coach never picks.
  { key: "developer", label: "Integrations", icon: Link2, adminOnly: true },
  // Platform-only, not account-admin. Its own description says these are "the
  // services Clarity itself runs on, not things a coach picks" -- shared
  // infrastructure whose state belongs to the platform, not to any one
  // business. Gated on adminOnly it was visible to every business owner, so a
  // brand new workspace could see the platform's Resend, Drive and Stripe
  // wiring and read another business's Google connection as its own.
  { key: "admin", label: "Admin", icon: Code2, platformOnly: true },
];

